//! Format step 1 to 2, generated by `cargo run migration snapshot`.

use crate::{v1, v2};
use migration_core::{MigrationError, Upgrade, format_migration};

// Payloads keep their encoding. The bump stops builds without declaration versions from reading a later version as the first.
format_migration! {
	1 => 2,
}

impl Upgrade for v1::ProtoNode {
	type Next = v2::ProtoNode;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v1::ProtoNode { identifier, attributes } = self;
		Ok(v2::ProtoNode {
			identifier,
			// Declarations were unversioned before, so every one is the first of its lineage
			version: 1,
			attributes,
		})
	}
}
